Item.method_code:
/*
    開達実施要領一括承認のLC用
    承認依頼（品質一課担当者） に遷移
    参考：h4_Call_Promote_InReview
*/
string NextState = "ReqApproval_Q1Stf";

Innovator inn = this.getInnovator();
//引数（遷移先はハードコーディング）
Item callMethod = inn.newItem("method","h4_PromoteDATFormatOfAppWFGr");//開達実施要領一括承認向け
string id = this.getID();
callMethod.setProperty("destination", NextState);
callMethod.setProperty("sourceId", id);
//プロモートメソッド呼び出し
callMethod.apply();

return this;
